B.au2=new A.a7("Yeni \u015fifre",null,null,null,null,null,null,null,null,null,null)
B.au3=new A.a7("\xc7al\u0131\u015fma ve mola s\xfcrelerini, ard\u0131ndan tur say\u0131s\u0131n\u0131 se\xe7. B\xf6l\xfcmler s\u0131rayla ilerler; son \xe7al\u0131\u015fmadan sonra oturum biter.\n\nS\xfcre arka plandan d\xf6nd\xfc\u011f\xfcnde g\xfcncellenir. Web sitesi kapal\u0131yken ses veya bildirim gelmez. Mobilde mevcut b\xf6l\xfcm\xfcn biti\u015f uyar\u0131s\u0131, izinlere ve i\u015fletim sisteminin zamanlamas\u0131na ba\u011fl\u0131d\u0131r. Atlad\u0131\u011f\u0131n \xe7al\u0131\u015fma b\xf6l\xfcmleri tamamlanm\u0131\u015f say\u0131lmaz.",null,null,null,null,null,null,null,null,null,null)
B.au4=new A.a7("B\xf6l\xfcm\xfc ge\xe7",null,null,null,null,null,null,null,null,null,null)
B.au5=new A.a7("Hesap a\xe7arken saklad\u0131\u011f\u0131n kurtarma kodunu kullan. Bu i\u015flemden sonra yeni bir kod verilir.",null,null,null,null,null,null,null,null,null,null)
